import{readFileSync,writeFileSync,existsSync,copyFileSync}from'node:fs';import assert from'node:assert/strict';const f='docs/qa/R5_LEDGER_ACCIONES_404.json';const checkpoint='docs/qa/R5_LEDGER_ACCIONES_404.before-proposals-20261009.json';assert.ok(!existsSync(checkpoint));copyFileSync(f,checkpoint);const d=JSON.parse(readFileSync(f));const seen=new Set();for(const p of ['docs/qa/proposals/ledger-admin-ui-20261009.json','docs/qa/proposals/ledger-collaboration-ui-20261009.json']){const q=JSON.parse(readFileSync(p));for(const x of q.actions){assert.ok(!seen.has(x.actionId));seen.add(x.actionId);const a=d.actions.find(v=>v.actionId===x.actionId);assert.ok(a);const tests=(x.tests??[]).map(t=>typeof t==='string'?t:t.file);for(const file of [...tests,...(x.artifacts??[])])assert.ok(existsSync(file),file);a.evidenceAudit={...x,tests,proposalSource:p,interpretation:'Documental; no ejecución nueva ni aprobación visual. Estado propuesto preservado para revisar límites por control.'};if(a.executionState==='evidence-not-reconciled'&&(tests.length||(x.artifacts??[]).length)){a.tests=tests;a.artifacts=x.artifacts??[];a.currentControl=x.currentControl;a.commandOrNoWrite=x.commandOrNoWrite;a.candidateRelation=x.candidateRelation;a.executionState='evidence-mapped-review-pending';a.remaining=[...(x.remaining??[]),'Revisar correspondencia exacta por control y comparación UX base; no heredar VALIDADO.'];}}}assert.equal(seen.size,240);assert.equal(d.actions.length,404);d.updatedAt=new Date().toISOString();writeFileSync(f,JSON.stringify(d,null,2)+'\n');console.log(JSON.stringify({actions:404,documentaryAudits:240,newExecutionClaimed:false,visualApprovalClaimed:false}));
